server {
    listen 8443 ssl;
    server_name localhost;

    ssl_certificate /etc/nginx/certs/cert.pem;
    ssl_certificate_key /etc/nginx/certs/key.pem;

    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:!MD5;

    # Main branch content at /index.html
    location = /index.html {
        root /var/www/app/main;
        try_files $uri =404;
    }

    # Dev branch content at /dev/index.html
    location = /dev/index.html {
        root /var/www/app/dev;
        try_files $uri =404;
    }

    # Serve dev branch files from /dev/ path
    location /dev/ {
        root /var/www/app/dev;
        rewrite ^/dev/(.*)$ /$1 break;
    }

    # Root handler
    location / {
        root /var/www/app/main;
    }
}

